object Orders : Table("orders") {
    val id = long("id")
    val due = date("due")
    val total = decimal("total", 12, 2)
}

fun Orders.overdue(asOf: LocalDate): List<ResultRow> =
    selectAll().where { Orders.due less asOf }.toList()

fun Orders.flagOverdue(asOf: LocalDate): Int =
    update({ Orders.due less asOf }) { it[flagged] = true }
